mapper.update:
update wo_category
name = #{name}, biz_type = #{bizType}, icon = #{icon}, sort = #{sort}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select c.id, c.name, c.biz_type, c.sort, c.status, (select count(*) from svc_item i where i.category_id = c.id) as item_count from wo_category c
and c.name like concat('%', #{name}, '%') and c.biz_type = #{bizType} and c.status = #{status}
order by c.sort
